import io
from fastapi.responses import StreamingResponse

def chunks():
    with io.StringIO("payload") as handle:
        while chunk := handle.read(4):
            yield chunk

def response():
    return StreamingResponse(chunks())

probe:
import asyncio
async def probe():
    try:
        print("".join([chunk async for chunk in response().body_iterator]))
    except ValueError as exc:
        if "closed file" not in str(exc):
            raise
        print("closed-before-consumption")
asyncio.run(probe())
